 'Amarant Coral':op.event==='oracleDamageHit'&&op.eventFilter?.source?.kind==='self'&&op.eventFilter?.recipient?.kind==='an opponent'&&op.eventFilter?.combat===true&&op.effects.length===1&&op.effects[0].action==='common-effects-v58'&&op.effects[0].mode==='other-opponent-damage',
